    const copy={ru:{projects:'Проекты',contact:'Контакты',intro:'Создаю игры на Unity: от игровых механик до архитектуры сложных систем. Мобильные игры, образовательные миры и XR.',see:'Смотреть проекты ↗',write:'Связаться',concept:'КОНЦЕПТ ГРАФИКИ · НЕ КАДР ИЗ ИГРЫ',years:'лет в gamedev',systems:'систем в Al Galaxy',mini:'обучающих мини-игр',selected:'Избранные проекты',cover:'ЭСКИЗ ОБЛОЖКИ',galaxyTitle:'Мир, в котором учатся играя',galaxyText:'ECS-системы, взаимодействия персонажей, кастомизация, сохранения и ежедневные задания.',gibbetsTitle:'От разработки до релиза',gibbetsText:'Мобильная аркада HeroCraft. Участие в разработке и выпуске коммерческого проекта.',store:'Открыть Google Play ↗',publisher:'Страница издателя ↗',location:'Олег Карсункин · Сербия'},en:{projects:'Projects',contact:'Contact',intro:'I build Unity games, from gameplay mechanics to complex systems architecture. Mobile games, educational worlds, and XR.',see:'Explore projects ↗',write:'Get in touch',concept:'VISUAL CONCEPT · NOT GAME FOOTAGE',years:'years in gamedev',systems:'systems in Al Galaxy',mini:'educational mini-games',selected:'Selected projects',cover:'COVER CONCEPT',galaxyTitle:'A world of playful learning',galaxyText:'ECS systems, character interactions, customization, saving, and daily learning activities.',gibbetsTitle:'From development to release',gibbetsText:'A mobile arcade game by HeroCraft. Contributed to development and commercial release.',store:'View on Google Play ↗',publisher:'Publisher page ↗',location:'Oleg Karsunkin · Serbia'}};
    Object.assign(copy.ru,{"aboutTitle": "Игры, системы и немного обо мне", "aboutText": "Я Олег Карсункин, Unity Developer с 10+ годами опыта в игровой разработке. Работал над мобильными играми, образовательными проектами, Windows-портами и AR/MR-приложениями. Живу в Сербии. Особенно интересны проекты, где игровой опыт помогает исследовать и учиться.", "stackTitle": "Основной стек", "stackPlatforms": "Платформы: Android, iOS, Windows, WebGL, HoloLens", "aboutNav": "Обо мне", "footerInvite": "Обсудим ваш проект?", "footerLocation": "Сербия · Unity / C# Developer"});
    Object.assign(copy.en,{"aboutTitle": "Games, systems, and a little about me", "aboutText": "I’m Oleg Karsunkin, a Unity Developer with 10+ years of game development experience. My work spans mobile games, educational projects, Windows ports, and AR/MR applications. Based in Serbia, I’m especially interested in games that help people explore and learn.", "stackTitle": "Core stack", "stackPlatforms": "Platforms: Android, iOS, Windows, WebGL, HoloLens", "aboutNav": "About", "footerInvite": "Let’s talk about your project.", "footerLocation": "Serbia · Unity / C# Developer"});
    const titles={showcase:{ru:'Игровые миры.\nПродуманные системы.',en:'Playful worlds.\nThoughtful systems.'},playground:{ru:'Серьёзный код.\nЖивые миры.',en:'Serious code.\nPlayful worlds.'},workshop:{ru:'Геймплей снаружи.\nАрхитектура внутри.',en:'Gameplay outside.\nArchitecture inside.'}};
    const projectData=JSON.parse(document.getElementById('op-project-data').textContent).projects;
